+        margin: 0.2rem 0 0;
+        accent-color: var(--accent);
+        flex: 0 0 auto;
+      }
+
+      .checkbox-copy {
+        display: grid;
+        gap: 6px;
+      }
+
+      label {
+        font-weight: 600;
+        line-height: 1.45;
+        cursor: pointer;
+      }
+
+      .required {
+        color: var(--error);
+      }
+
+      .helper-text,
+      .error-text {
+        margin: 0;
+        font-size: 0.9375rem;
+        line-height: 1.5;
+      }
+
+      .helper-text {
+        color: var(--muted);
+      }
+
+      .error-text {
+        color: var(--error);
+        font-weight: 500;
+      }
+
+      .actions {
+        display: flex;
+        justify-content: flex-end;
+      }
+
+      button {
+        appearance: none;
+        border: 0;
+        border-radius: 999px;
+        padding: 0.875rem 1.4rem;
+        font: inherit;
+        font-weight: 700;
+        color: #fff;
+        background: linear-gradient(180deg, var(--accent), var(--accent-strong));
+        box-shadow: 0 12px 24px rgba(36, 87, 255, 0.24);
+        cursor: pointer;
+      }
+
+      button:hover {
+        filter: brightness(1.03);
+      }
+
+      button:focus-visible,
+      input:focus-visible {
+        outline: 3px solid #1a73e8;
+        outline-offset: 3px;
+      }
+
+      [hidden] {
+        display: none !important;
+      }
+
+      @media (max-width: 420px) {
+        .card {
+          padding: 24px;
+        }
+
+        .form-field {
+          padding: 16px;
+        }
+
+        .actions {
+          justify-content: stretch;
