   <body>
     <main class="page">
       <section class="card" aria-labelledby="page-title">
         <p class="eyebrow">Account access</p>
         <h1 id="page-title">Consent to the terms of use</h1>
         <p class="description">
           Review the terms and confirm your agreement to continue.
         </p>

         <form id="consent-form" novalidate>
           <div class="form-field">
             <div class="checkbox-row">
               <input
                 id="agree-terms"
                 name="agreeTerms"
                 type="checkbox"
                 required
                 aria-describedby="agree-help"
               />
               <div class="checkbox-copy">
                 <label for="agree-terms">
                   I agree to the terms of use <span class="required" aria-hidden="true">*</span>
                 </label>
                 <p id="agree-help" class="helper-text">
                   Required to proceed with your account.
                 </p>
                 <p id="agree-error" class="error-text" hidden>
                   Error: You must agree to the terms of use to continue.
                 </p>
               </div>
             </div>
           </div>

           <div class="actions">
             <button type="submit">Continue</button>
           </div>

           <p id="form-status" class="status-text" role="status" aria-live="polite" hidden></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.getElementById("consent-form");
       const checkbox = document.getElementById("agree-terms");
       const helpTextId = "agree-help";
       const errorTextId = "agree-error";
       const errorText = document.getElementById("agree-error");
       const statusText = document.getElementById("form-status");

       function setCheckboxError(isInvalid) {
         checkbox.setAttribute("aria-describedby", isInvalid ? `${helpTextId} ${errorTextId}` : helpTextId);
         if (isInvalid) {
           checkbox.setAttribute("aria-invalid", "true");
         } else {
           checkbox.removeAttribute("aria-invalid");
         }
         errorText.hidden = !isInvalid;
       }

       function setStatus(message) {
         statusText.textContent = message;
         statusText.hidden = !message;
       }

       form.addEventListener("submit", (event) => {
         if (!checkbox.checked) {
           event.preventDefault();
           setCheckboxError(true);
           setStatus("");
           checkbox.focus();
           return;
         }

         setCheckboxError(false);
         event.preventDefault();
         setStatus("Consent saved. You can continue.");
       });

       checkbox.addEventListener("change", () => {
         if (checkbox.checked) {
           setCheckboxError(false);
           setStatus("");
         }
       });
     </script>
   </body>
